import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv1d_source = r'''
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <vector>

__global__ void conv1d_kernel(
    const float* input,
    const float* weight,
    const float* bias,
    float* output,
    int B,
    int IN_C,
    int IN_L,
    int OUT_C,
    int K,
    int stride,
    int dilation,
    int OUT_L,
    bool has_bias
) {
    int out_pos = blockIdx.x * blockDim.x + threadIdx.x;
    int oc = blockIdx.y * blockDim.y + threadIdx.y;
    int b = blockIdx.z * blockDim.z + threadIdx.z;

    if (b < B && oc < OUT_C && out_pos < OUT_L) {
        float val = 0.0f;
        for (int ic = 0; ic < IN_C; ic++) {
            for (int k = 0; k < K; k++) {
                int in_pos = out_pos * stride + k * dilation;
                if (in_pos < IN_L) {
                    val += input[((b * IN_C + ic) * IN_L) + in_pos] *
                           weight[((oc * IN_C + ic) * K) + k];
                }
            }
        }
        if (has_bias) {
            val += bias[oc];
        }
        output[((b * OUT_C + oc) * OUT_L) + out_pos] = val;
    }
}

torch::Tensor conv1d_forward_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::optional<torch::Tensor> bias_opt,
    int stride,
    int dilation
) {
    // Shapes
    int B = input.size(0);
    int IN_C = input.size(1);
    int IN_L = input.size(2);

    int OUT_C = weight.size(0);
    int K = weight.size(2);

    // Compute output length (naive integer division)
    int OUT_L = (IN_L - dilation * (K - 1) - 1) / stride + 1;
    auto output = torch::zeros({B, OUT_C, OUT_L}, input.options());

    bool has_bias = false;
    float* bias_data = nullptr;
    if (bias_opt.has_value()) {
        has_bias = true;
        bias_data = bias_opt.value().data_ptr<float>();
    }

    const float* input_data = input.data_ptr<float>();
    const float* weight_data = weight.data_ptr<float>();
    float* output_data = output.data_ptr<float>();

    // Kernel launch
    dim3 block(16, 16, 1);
    dim3 grid((OUT_L + block.x - 1) / block.x,
              (OUT_C + block.y - 1) / block.y,
              (B + block.z - 1) / block.z);

    conv1d_kernel<<<grid, block>>>(
        input_data,
        weight_data,
        bias_data,
        output_data,
        B, IN_C, IN_L,
        OUT_C, K,
        stride, dilation,
        OUT_L,
        has_bias
    );
    return output;
}
'''

conv1d_cpp_source = r'''
torch::Tensor conv1d_forward_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::optional<torch::Tensor> bias_opt,
    int stride,
    int dilation
);
'''

conv1d_op = load_inline(
    name="conv1d_op",
    cpp_sources=conv1d_cpp_source,
    cuda_sources=conv1d_source,
    functions=["conv1d_forward_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    Custom 1D convolution with a fused CUDA kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, dilation: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.dilation = dilation
        self.has_bias = bias

        # Initialize weight and bias
        self.weight = nn.Parameter(torch.randn(out_channels, in_channels, kernel_size))
        if bias:
            self.bias = nn.Parameter(torch.randn(out_channels))
        else:
            self.register_parameter('bias', None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return conv1d_op.conv1d_forward_cuda(
            x,
            self.weight,
            self.bias if self.has_bias else None,
            self.stride,
            self.dilation
        )
